using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace Needle.Generators;

internal static class Emitter
{
    public static string Emit(ToolSetModel model, bool implementToolSet)
    {
        var builder = new StringBuilder(4096);
        builder.Append("""
            // <auto-generated by Needle.Generators (W10); do not edit.>
            #nullable enable
            """);
        builder.Append('\n');
        if (!model.GlobalNamespace)
        {
            builder.Append("namespace ").Append(model.Namespace).Append("\n{\n");
        }
        var indent = model.GlobalNamespace ? "" : "    ";
        EmitKindEnum(builder, model, indent);
        foreach (var tool in model.Tools) EmitArgsStruct(builder, model, tool, indent);
        EmitCommandStruct(builder, model, indent);
        EmitCommandsClass(builder, model, indent);
        if (implementToolSet) EmitToolSetAdapter(builder, model, indent);
        if (!model.GlobalNamespace) builder.Append("}\n");
        return builder.ToString();
    }

    static void EmitToolSetAdapter(StringBuilder builder, ToolSetModel model, string indent)
    {
        var name = ToolSetName(model);
        builder.Append(indent).Append("public readonly struct ").Append(name).Append(" : global::Needle.Tools.IToolSet\n");
        builder.Append(indent).Append("{\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<byte> Schema => ").Append(model.CommandsName).Append(".Schema;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarNodes => ").Append(model.CommandsName).Append(".GrammarNodes;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarProperties => ").Append(model.CommandsName).Append(".GrammarProperties;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarLiterals => ").Append(model.CommandsName).Append(".GrammarLiterals;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarUnions => ").Append(model.CommandsName).Append(".GrammarUnions;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarTools => ").Append(model.CommandsName).Append(".GrammarTools;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<byte> GrammarBytes => ").Append(model.CommandsName).Append(".GrammarBytes;\n");
        builder.Append(indent).Append("    public static int GrammarRoot => ").Append(model.CommandsName).Append(".GrammarRoot;\n");
        builder.Append(indent).Append("    public static int GrammarToolCount => ").Append(model.CommandsName).Append(".GrammarToolCount;\n");
        builder.Append(indent).Append("}\n\n");
    }

    static string ToolSetName(ToolSetModel model) => model.CommandName.EndsWith("Command", StringComparison.Ordinal)
        ? model.CommandName.Substring(0, model.CommandName.Length - "Command".Length) + "ToolSet"
        : model.CommandName + "ToolSet";

    static void EmitKindEnum(StringBuilder builder, ToolSetModel model, string indent)
    {
        builder.Append(indent).Append("public enum ").Append(model.CommandName).Append("Kind : byte\n").Append(indent).Append("{\n");
        builder.Append(indent).Append("    None = 0,\n");
        for (var i = 0; i < model.Tools.Length; i++)
            builder.Append(indent).Append("    ").Append(model.Tools[i].Name).Append(" = ").Append(i + 1).Append(",\n");
        builder.Append(indent).Append("}\n\n");
    }

    static void EmitArgsStruct(StringBuilder builder, ToolSetModel model, ToolEntry tool, string indent)
    {
        builder.Append(indent).Append("public struct ").Append(tool.Name).Append("Args\n").Append(indent).Append("{\n");
        foreach (var arg in tool.Args)
            builder.Append(indent).Append("    public ").Append(arg.SlotTypeName).Append(' ').Append(Pascal(arg.Name)).Append(";\n");
        builder.Append(indent).Append("}\n\n");
    }

    static void EmitCommandStruct(StringBuilder builder, ToolSetModel model, string indent)
    {
        builder.Append(indent).Append("public struct ").Append(model.CommandName).Append('\n').Append(indent).Append("{\n");
        builder.Append(indent).Append("    public ").Append(model.CommandName).Append("Kind Kind;\n");
        builder.Append(indent).Append("    public uint Presence;\n");
        foreach (var tool in model.Tools)
            builder.Append(indent).Append("    public ").Append(tool.Name).Append("Args ").Append(tool.Name).Append(";\n");
        builder.Append(indent).Append("}\n\n");
    }

    static void EmitCommandsClass(StringBuilder builder, ToolSetModel model, string indent)
    {
        builder.Append(indent).Append("public static ").Append("class ").Append(model.CommandsName).Append('\n');
        builder.Append(indent).Append("{\n");
        builder.Append(indent).Append("    public const int ToolCount = ").Append(model.Tools.Length).Append(";\n\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<byte> Schema => \"").Append(CSharpEscape(SchemaText(model))).Append("\"u8;\n\n");
        EmitGrammarTables(builder, model, indent);
        EmitDispatch(builder, model, indent);
        EmitBind(builder, model, indent);
        EmitEnumReaders(builder, model, indent);
        builder.Append(indent).Append("}\n");
    }

    static void EmitGrammarTables(StringBuilder builder, ToolSetModel model, string indent)
    {
        var nodes = new List<int>();
        var properties = new List<int>();
        var literals = new List<int>();
        var unions = new List<int>();
        var bytes = new List<byte>();
        AddNode(nodes, 0, 0, 0, 0, 0);
        AddNode(nodes, 1, -1, 0, 0, 0);
        AddNode(nodes, 2, 0, 0, 0, 0);
        AddNode(nodes, 3, 0, 0, 0, 0);
        AddNode(nodes, 4, 0, 0, 0, 0);
        AddNode(nodes, 5, 0, 0, 0, 0);
        AddNode(nodes, 6, 0, 0, -1, 0);
        AddNode(nodes, 7, 0, 0, 0, 1);
        AddNode(nodes, 11, 0, 0, 0, 0);
        AddNode(nodes, 10, 0, 0, 0, 0);
        var argumentNodes = new List<int>();
        foreach (var tool in model.Tools) argumentNodes.Add(CompileObject(tool, nodes, properties, literals, unions, bytes));
        var tools = new List<int>();
        for (var i = 0; i < model.Tools.Length; i++)
        {
            var raw = Encoding.UTF8.GetBytes(model.Tools[i].Alias);
            tools.Add(bytes.Count);
            tools.Add(raw.Length);
            tools.Add(argumentNodes[i]);
            tools.Add(0);
            bytes.AddRange(raw);
        }
        nodes[9 * 8 + 1] = model.Tools.Length;
        nodes[9 * 8 + 2] = 0;

        builder.Append(indent).Append("    static readonly int[] NodeTable = new int[] { ").Append(Join(nodes)).Append(" };\n");
        builder.Append(indent).Append("    static readonly int[] PropertyTable = ").Append(Table(properties)).Append(";\n");
        builder.Append(indent).Append("    static readonly int[] LiteralTable = ").Append(Table(literals)).Append(";\n");
        builder.Append(indent).Append("    static readonly int[] UnionTable = ").Append(Table(unions)).Append(";\n");
        builder.Append(indent).Append("    static readonly int[] ToolTable = ").Append(Table(tools)).Append(";\n");
        builder.Append(indent).Append("    static readonly byte[] ByteTable = ").Append(ByteTable(bytes)).Append(";\n");
        builder.Append(indent).Append("    public const int GrammarRoot = 9;\n");
        builder.Append(indent).Append("    public const int GrammarToolCount = ").Append(model.Tools.Length).Append(";\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarNodes => NodeTable;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarProperties => PropertyTable;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarLiterals => LiteralTable;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarUnions => UnionTable;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<int> GrammarTools => ToolTable;\n");
        builder.Append(indent).Append("    public static System.ReadOnlySpan<byte> GrammarBytes => ByteTable;\n\n");
    }

    static string Table(List<int> values) => values.Count == 0 ? "System.Array.Empty<int>()" : "new int[] { " + Join(values) + " }";

    static string ByteTable(List<byte> values) => values.Count == 0
        ? "System.Array.Empty<byte>()"
        : "new byte[] { " + string.Join(", ", values) + " }";

    static string Join(List<int> values) => string.Join(", ", values);

    static int CompileObject(ToolEntry tool, List<int> nodes, List<int> properties, List<int> literals, List<int> unions, List<byte> bytes)
    {
        var required = 0;
        var children = new List<int>();
        foreach (var arg in tool.Args)
        {
            if (!arg.Optional) required |= 1 << children.Count;
            children.Add(CompileValue(arg, literals, bytes, nodes));
        }
        var first = properties.Count / 4;
        foreach (var arg in tool.Args)
        {
            var raw = Encoding.UTF8.GetBytes(arg.Alias);
            properties.Add(bytes.Count);
            properties.Add(raw.Length);
            properties.Add(children[properties.Count / 4 - first]);
            properties.Add(0);
            bytes.AddRange(raw);
        }
        return AddNode(nodes, 7, tool.Args.Length, first, required, 0);
    }

    static int CompileValue(ToolArg arg, List<int> literals, List<byte> bytes, List<int> nodes)
    {
        switch (arg.Type)
        {
            case ArgType.Int:
            case ArgType.Long: return 2;
            case ArgType.Float:
            case ArgType.Double: return 3;
            case ArgType.Bool: return 4;
            case ArgType.Text: return AddNode(nodes, 1, arg.FixedText ? arg.TextCapacity : -1, 0, 0, 0);
        }
        var first = literals.Count / 2;
        foreach (var literal in arg.EnumLiterals)
        {
            var raw = Encoding.UTF8.GetBytes(Quote(literal));
            literals.Add(bytes.Count);
            literals.Add(raw.Length);
            bytes.AddRange(raw);
        }
        return AddNode(nodes, 8, arg.EnumLiterals.Length, first, 0, 0);
    }

    static int AddNode(List<int> nodes, int kind, int a, int b, int c, int d)
    {
        var index = nodes.Count / 8;
        nodes.Add(kind);
        nodes.Add(a);
        nodes.Add(b);
        nodes.Add(c);
        nodes.Add(d);
        nodes.Add(0);
        nodes.Add(0);
        nodes.Add(0);
        return index;
    }

    static void EmitDispatch(StringBuilder builder, ToolSetModel model, string indent)
    {
        builder.Append(indent).Append("    public static void Dispatch<THandler>(ref THandler handler, in ").Append(model.CommandName)
            .Append(" command) where THandler : struct, ").Append(model.Q(model.InterfaceName)).Append('\n');
        builder.Append(indent).Append("    {\n");
        builder.Append(indent).Append("        switch (command.Kind)\n");
        builder.Append(indent).Append("        {\n");
        for (var t = 0; t < model.Tools.Length; t++)
        {
            var tool = model.Tools[t];
            builder.Append(indent).Append("            case ").Append(model.CommandName).Append("Kind.").Append(tool.Name).Append(":\n");
            var arguments = new List<string>();
            for (var p = 0; p < tool.Args.Length; p++)
            {
                var arg = tool.Args[p];
                var field = $"command.{tool.Name}.{Pascal(arg.Name)}";
                var value = arg.Type == ArgType.Text && !arg.PassTextThrough ? field + ".ToString()" : field;
                if (arg.Optional) value = $"(command.Presence & 0x{1u << p:x}u) != 0 ? {value} : {arg.DefaultLiteral}";
                arguments.Add(value);
            }
            builder.Append(indent).Append("                handler.").Append(tool.Name).Append('(').Append(string.Join(", ", arguments)).Append(");\n");
            builder.Append(indent).Append("                break;\n");
        }
        builder.Append(indent).Append("        }\n");
        builder.Append(indent).Append("    }\n\n");
    }

    static void EmitBind(StringBuilder builder, ToolSetModel model, string indent)
    {
        builder.Append(indent).Append("    public static bool TryBind(in global::Needle.FunctionCall call, out ").Append(model.CommandName).Append(" command)\n");
        builder.Append(indent).Append("    {\n");
        builder.Append(indent).Append("        command = default;\n");
        builder.Append(indent).Append("        switch (call.Name)\n");
        builder.Append(indent).Append("        {\n");
        foreach (var tool in model.Tools)
        {
            builder.Append(indent).Append("            case \"").Append(CSharpEscape(tool.Alias)).Append("\":\n");
            builder.Append(indent).Append("            {\n");
            builder.Append(indent).Append("                command.Kind = ").Append(model.CommandName).Append("Kind.").Append(tool.Name).Append(";\n");
            builder.Append(indent).Append("                var parsed = global::Needle.JsonValue.Parse(call.ArgumentsJson);\n");
            builder.Append(indent).Append("                if (parsed.Kind == global::Needle.JsonKind.Object)\n");
            builder.Append(indent).Append("                    foreach (var member in parsed.Members)\n");
            builder.Append(indent).Append("                    {\n");
            builder.Append(indent).Append("                        switch (member.Key)\n");
            builder.Append(indent).Append("                        {\n");
            for (var p = 0; p < tool.Args.Length; p++)
            {
                var arg = tool.Args[p];
                var target = $"command.{tool.Name}.{Pascal(arg.Name)}";
                builder.Append(indent).Append("                            case \"").Append(CSharpEscape(arg.Name)).Append("\":\n");
                switch (arg.Type)
                {
                    case ArgType.Int:
                    case ArgType.Long:
                        var parser = arg.Type == ArgType.Int ? "int" : "long";
                        builder.Append(indent).Append("                                if (member.Value.Kind == global::Needle.JsonKind.Number && ").Append(parser)
                            .Append(".TryParse(member.Value.Text, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out var n").Append(p).Append("))\n");
                        builder.Append(indent).Append("                                {\n");
                        builder.Append(indent).Append("                                    ").Append(target).Append(" = n").Append(p).Append(";\n");
                        AppendPresence(builder, indent, p, 9);
                        builder.Append(indent).Append("                                }\n");
                        break;
                    case ArgType.Float:
                    case ArgType.Double:
                        var floatParser = arg.Type == ArgType.Float ? "float" : "double";
                        builder.Append(indent).Append("                                if (member.Value.Kind == global::Needle.JsonKind.Number && ").Append(floatParser)
                            .Append(".TryParse(member.Value.Text, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var n").Append(p).Append("))\n");
                        builder.Append(indent).Append("                                {\n");
                        builder.Append(indent).Append("                                    ").Append(target).Append(" = n").Append(p).Append(";\n");
                        AppendPresence(builder, indent, p, 9);
                        builder.Append(indent).Append("                                }\n");
                        break;
                    case ArgType.Bool:
                        builder.Append(indent).Append("                                if (member.Value.Kind == global::Needle.JsonKind.Bool)\n");
                        builder.Append(indent).Append("                                {\n");
                        builder.Append(indent).Append("                                    ").Append(target).Append(" = member.Value.Boolean;\n");
                        AppendPresence(builder, indent, p, 9);
                        builder.Append(indent).Append("                                }\n");
                        break;
                    case ArgType.Enum:
                        var reader = EnumReaderName(arg);
                        builder.Append(indent).Append("                                if (member.Value.Kind == global::Needle.JsonKind.String)\n");
                        builder.Append(indent).Append("                                {\n");
                        builder.Append(indent).Append("                                    ").Append(target).Append(" = ").Append(reader).Append("(member.Value.Text);\n");
                        AppendPresence(builder, indent, p, 9);
                        builder.Append(indent).Append("                                }\n");
                        break;
                    default:
                        builder.Append(indent).Append("                                if (member.Value.Kind == global::Needle.JsonKind.String)\n");
                        builder.Append(indent).Append("                                {\n");
                        builder.Append(indent).Append("                                    ").Append(target).Append(".Set(member.Value.Text);\n");
                        AppendPresence(builder, indent, p, 9);
                        builder.Append(indent).Append("                                }\n");
                        break;
                }
                builder.Append(indent).Append("                                break;\n");
            }
            builder.Append(indent).Append("                        }\n");
            builder.Append(indent).Append("                    }\n");
            builder.Append(indent).Append("                return true;\n");
            builder.Append(indent).Append("            }\n");
        }
        builder.Append(indent).Append("            default: return false;\n");
        builder.Append(indent).Append("        }\n");
        builder.Append(indent).Append("    }\n\n");
    }

    static void AppendPresence(StringBuilder builder, string indent, int bit, int tabs)
    {
        builder.Append(indent);
        for (var i = 0; i < tabs; i++) builder.Append("    ");
        builder.Append("command.Presence |= 0x").Append(1u << bit).Append("u;\n");
    }

    static void EmitEnumReaders(StringBuilder builder, ToolSetModel model, string indent)
    {
        var emitted = new HashSet<string>(StringComparer.Ordinal);
        foreach (var tool in model.Tools)
            foreach (var arg in tool.Args)
            {
                if (arg.Type != ArgType.Enum || !emitted.Add(arg.EnumTypeName!)) continue;
                builder.Append(indent).Append("    static ").Append(arg.EnumTypeName).Append(' ').Append(EnumReaderName(arg)).Append("(string text)\n");
                builder.Append(indent).Append("    {\n");
                builder.Append(indent).Append("        switch (text)\n");
                builder.Append(indent).Append("        {\n");
                for (var i = 0; i < arg.EnumLiterals.Length; i++)
                    builder.Append(indent).Append("            case \"").Append(CSharpEscape(arg.EnumLiterals[i])).Append("\": return ").Append(EnumMemberName(arg, i)).Append(";\n");
                builder.Append(indent).Append("            default: return default;\n");
                builder.Append(indent).Append("        }\n");
                builder.Append(indent).Append("    }\n\n");
            }
    }

    static string EnumReaderName(ToolArg arg)
    {
        var name = arg.EnumTypeName!;
        var dot = name.LastIndexOf('.');
        return dot >= 0 ? name.Substring(dot + 1) + "From" : name + "From";
    }

    static string EnumMemberName(ToolArg arg, int index) => arg.EnumTypeName! + "." + arg.EnumMembers[index];

    static string Pascal(string name) => name.Length == 0 ? name : char.ToUpperInvariant(name[0]) + name.Substring(1);

    static string CSharpEscape(string text)
    {
        var builder = new StringBuilder(text.Length + 8);
        foreach (var c in text)
            switch (c)
            {
                case '"': builder.Append("\\\""); break;
                case '\\': builder.Append("\\\\"); break;
                case '\n': builder.Append("\\n"); break;
                case '\r': builder.Append("\\r"); break;
                case '\t': builder.Append("\\t"); break;
                default: builder.Append(c); break;
            }
        return builder.ToString();
    }

    static string Quote(string text)
    {
        var builder = new StringBuilder(text.Length + 2);
        builder.Append('"');
        foreach (var c in text)
        {
            switch (c)
            {
                case '"': builder.Append("\\\""); break;
                case '\\': builder.Append("\\\\"); break;
                case '\n': builder.Append("\\n"); break;
                case '\r': builder.Append("\\r"); break;
                case '\t': builder.Append("\\t"); break;
                case '\b': builder.Append("\\b"); break;
                case '\f': builder.Append("\\f"); break;
                default:
                    if (c < 0x20) builder.Append("\\u").Append(((int)c).ToString("x4", CultureInfo.InvariantCulture));
                    else builder.Append(c);
                    break;
            }
        }
        builder.Append('"');
        return builder.ToString();
    }

    static string SchemaText(ToolSetModel model)
    {
        var builder = new StringBuilder(256);
        builder.Append('[');
        for (var i = 0; i < model.Tools.Length; i++)
        {
            if (i > 0) builder.Append(',');
            var tool = model.Tools[i];
            builder.Append("{\"name\":").Append(Quote(tool.Alias));
            builder.Append(",\"description\":").Append(Quote(tool.Description));
            builder.Append(",\"parameters\":{\"type\":\"object\",\"properties\":{");
            for (var p = 0; p < tool.Args.Length; p++)
            {
                if (p > 0) builder.Append(',');
                var arg = tool.Args[p];
                builder.Append(Quote(arg.Alias)).Append(':').Append(PropertySchema(arg));
            }
            builder.Append('}');
            var required = new List<string>();
            foreach (var arg in tool.Args)
                if (!arg.Optional) required.Add(Quote(arg.Alias));
            if (required.Count > 0) builder.Append(",\"required\":[").Append(string.Join(",", required)).Append(']');
            builder.Append("}}");
        }
        builder.Append(']');
        return builder.ToString();
    }

    static string PropertySchema(ToolArg arg)
    {
        var builder = new StringBuilder(64);
        builder.Append("{\"type\":");
        switch (arg.Type)
        {
            case ArgType.Int:
            case ArgType.Long:
                builder.Append("\"integer\"");
                break;
            case ArgType.Float:
            case ArgType.Double:
                builder.Append("\"number\"");
                break;
            case ArgType.Bool:
                builder.Append("\"boolean\"");
                break;
            default:
                builder.Append("\"string\"");
                break;
        }
        if (arg.Description is { Length: > 0 } description) builder.Append(",\"description\":").Append(Quote(description));
        if (arg.Type == ArgType.Enum)
        {
            builder.Append(",\"enum\":[");
            for (var i = 0; i < arg.EnumLiterals.Length; i++)
            {
                if (i > 0) builder.Append(',');
                builder.Append(Quote(arg.EnumLiterals[i]));
            }
            builder.Append(']');
        }
        if (arg.Type == ArgType.Text && arg.FixedText) builder.Append(",\"maxLength\":").Append(arg.TextCapacity.ToString(CultureInfo.InvariantCulture));
        builder.Append('}');
        return builder.ToString();
    }
}
